"""Update 6 (the Return of the Celts): script. Writes (all with BOM):
  common/scripted_triggers/eir_triggers_celt.txt
  common/scripted_effects/eir_effects_celt.txt
  common/on_action/eir_on_actions_celt.txt"""
from eir_lib import *
from celt_data import REGIONS
from gen_script_brit import N_BRIT

T = ["""##########################################################################
# Eire Reborn - Update 6 (Return of the Celts) triggers, generated by tools/gen_script_celt.py
##########################################################################

# Every county of the Empire of Britannia.
eir_brit_100_trigger = {
	any_sub_realm_county = {
		count >= %d
		empire = title:e_britannia
	}
}

# An Irish emperor.
eir_irish_emperor_trigger = {
	culture = culture:irish
	highest_held_title_tier >= tier_empire
}

# A ruler whose culture took the Forest Warriors tradition.
eir_forest_culture_trigger = {
	culture ?= { has_cultural_parameter = eir_forest_warriors }
}
""" % N_BRIT]
E = ["""##########################################################################
# Eire Reborn - Update 6 (Return of the Celts) effects, generated by tools/gen_script_celt.py
##########################################################################

# County scope (root = the ruler): the county takes the ruler's culture and resents it for a while.
eir_celt_convert_county_effect = {
	set_county_culture = root.culture
	add_county_modifier = {
		modifier = eir_mainland_resistance_modifier
		years = 15
	}
}
"""]
PULSE = []
for k, r in REGIONS.items():
    T.append(f"""
eir_celt_{k}_claim_trigger = {{
	any_sub_realm_county = {{
		count >= {r['claim_n']}
		{r['area']}
	}}
}}

eir_celt_{k}_conquest_trigger = {{
	any_sub_realm_county = {{
		count >= {r['conq_n']}
		{r['area']}
	}}
}}
""")
    E.append(f"""
# Character scope: half of the counties of {r['area_name']} in the realm that are not of the ruler's culture take it.
eir_celt_half_convert_{k}_effect = {{
	every_sub_realm_county = {{
		limit = {{
			{r['area']}
			NOT = {{ culture = root.culture }}
		}}
		random = {{
			chance = 50
			eir_celt_convert_county_effect = yes
		}}
	}}
}}
""")
    PULSE.append(f"""		if = {{
			limit = {{ has_character_modifier = eir_return_{k}_modifier }}
			every_sub_realm_county = {{
				limit = {{
					{r['area']}
					NOT = {{ culture = root.culture }}
				}}
				random = {{
					chance = 6
					eir_celt_convert_county_effect = yes
				}}
			}}
		}}
""")

ONACTION = """##########################################################################
# Eire Reborn - Update 6 on_actions, generated by tools/gen_script_celt.py
# Hooked into random_yearly_playable_pulse in eir_on_actions.txt
##########################################################################

# Once a year, every foreign county of a region under a Return of the Celts modifier has a 6% chance (1% x 5 + 1%) to take the ruler's culture.
eir_celt_conversion_pulse = {
	trigger = {
		eir_is_gael_ruler_trigger = yes
		is_ai = no
		OR = {
""" + "".join("\t\t\thas_character_modifier = eir_return_%s_modifier\n" % k for k in REGIONS) + """		}
	}
	effect = {
""" + "".join(PULSE) + """	}
}

# Once a year, the Forest Warriors' culture refreshes its blessing in every county of Britannia that the ruler holds.
eir_forest_dominion_pulse = {
	trigger = {
		is_ruler = yes
		eir_forest_culture_trigger = yes
	}
	effect = {
		every_sub_realm_county = {
			limit = { empire = title:e_britannia }
			add_county_modifier = {
				modifier = eir_forest_dominion_modifier
				years = 2
			}
		}
	}
}
"""


def build():
    write("common/scripted_triggers/eir_triggers_celt.txt", "".join(T))
    write("common/scripted_effects/eir_effects_celt.txt", "".join(E))
    write("common/on_action/eir_on_actions_celt.txt", ONACTION)
    print("script celt written")


if __name__ == "__main__":
    build()
